#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/x509.h>
#include <openssl/x509_vfy.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

#define MAX_CLIENTS 64
#define UPLOAD_DIR "/var/chat/uploads/"
#define CA_BUNDLE "/etc/ssl/certs/ca-certificates.crt"

typedef struct {
    int fd;
    SSL *ssl;
    char username[64];
    int verified;
} client_t;

static client_t clients[MAX_CLIENTS];
static pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;

/* Custom verification callback for client certificate chains.
 * We implement a depth-limited verification to prevent overly
 * long certificate chains from causing DoS. */
static int cert_verify_callback(int preverify_ok, X509_STORE_CTX *ctx) {
    int depth = X509_STORE_CTX_get_error_depth(ctx);
    int err = X509_STORE_CTX_get_error(ctx);

    /* Limit chain depth to 3 */
    if (depth > 3) {
        X509_STORE_CTX_set_error(ctx, X509_V_ERR_CERT_CHAIN_TOO_LONG);
        return 0;
    }

    /* For self-signed certificates at depth 0, we allow them
     * if they match our pinned key format (handled post-handshake).
     * At intermediate depths, require valid chain. */
    if (depth == 0 && err == X509_V_ERR_DEPTH_ZERO_SELF_SIGNED_CERT) {
        /* Self-signed client certs are acceptable for chat;
         * actual authorization happens via username/token binding */
        return 1;
    }

    /* For expired certificates, reject them - no grace period
     * for security-sensitive upload operations */
    if (err == X509_V_ERR_CERT_HAS_EXPIRED) {
        return 0;
    }

    /* For untrusted root at any depth, reject the chain.
     * Only certificates chaining to our CA bundle are accepted
     * for non-self-signed scenarios. */
    if (err == X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT_LOCALLY ||
        err == X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT) {
        return 0;
    }

    return preverify_ok;
}

/* Validate uploaded file's embedded signature against the
 * client's presented certificate */
static int validate_upload_signature(SSL *ssl, const unsigned char *data,
                                      size_t data_len, const unsigned char *sig,
                                      size_t sig_len) {
    X509 *peer_cert = SSL_get_peer_certificate(ssl);
    if (!peer_cert) return -1;

    EVP_PKEY *pkey = X509_get_pubkey(peer_cert);
    if (!pkey) {
        X509_free(peer_cert);
        return -1;
    }

    EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
    if (!md_ctx) {
        EVP_PKEY_free(pkey);
        X509_free(peer_cert);
        return -1;
    }

    int result = -1;
    if (EVP_DigestVerifyInit(md_ctx, NULL, EVP_sha256(), NULL, pkey) == 1 &&
        EVP_DigestVerifyUpdate(md_ctx, data, data_len) == 1) {
        result = EVP_DigestVerifyFinal(md_ctx, sig, sig_len);
    }

    EVP_MD_CTX_free(md_ctx);
    EVP_PKEY_free(pkey);
    X509_free(peer_cert);

    return result == 1 ? 0 : -1;
}

/* Reject strings that could be used for path traversal */
static int is_safe_path_component(const char *s) {
    if (!s || s[0] == '\0') return 0;
    if (strchr(s, '/') || strchr(s, '\\') || strstr(s, "..")) return 0;
    return 1;
}

/* Process file upload from authenticated client */
static int handle_upload(client_t *client, const char *filename,
                         const unsigned char *payload, size_t payload_len) {
    /* Sanitize filename */
    if (!is_safe_path_component(filename)) {
        return -1;
    }

    /* Sanitize username as well, since it is used in the path */
    if (!is_safe_path_component(client->username)) {
        return -1;
    }

    /* Extract signature (last 256 bytes) and data */
    if (payload_len <= 256) return -1;
    size_t data_len = payload_len - 256;
    const unsigned char *sig = payload + data_len;

    /* Verify the upload is signed by the client's cert */
    if (validate_upload_signature(client->ssl, payload, data_len,
                                   sig, 256) != 0) {
        fprintf(stderr, "Upload signature verification failed for %s\n",
                client->username);
        return -1;
    }

    /* Write to upload directory */
    char path[512];
    int n = snprintf(path, sizeof(path), "%s%s_%s", UPLOAD_DIR,
                     client->username, filename);
    if (n < 0 || (size_t)n >= sizeof(path)) {
        return -1;
    }

    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    if (fwrite(payload, 1, data_len, f) != data_len) {
        fclose(f);
        return -1;
    }
    fclose(f);

    return 0;
}

SSL_CTX *create_server_context(void) {
    SSL_CTX *ctx = SSL_CTX_new(TLS_server_method());
    if (!ctx) return NULL;

    SSL_CTX_set_min_proto_version(ctx, TLS1_2_VERSION);
    if (SSL_CTX_load_verify_locations(ctx, CA_BUNDLE, NULL) != 1) {
        SSL_CTX_free(ctx);
        return NULL;
    }

    /* Request client certificate but don't require it -
     * anonymous users can read, verified users can upload */
    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, cert_verify_callback);

    if (SSL_CTX_use_certificate_file(ctx, "/etc/chat/server.crt", SSL_FILETYPE_PEM) != 1) {
        SSL_CTX_free(ctx);
        return NULL;
    }
    if (SSL_CTX_use_PrivateKey_file(ctx, "/etc/chat/server.key", SSL_FILETYPE_PEM) != 1) {
        SSL_CTX_free(ctx);
        return NULL;
    }
    if (SSL_CTX_check_private_key(ctx) != 1) {
        SSL_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

int main(int argc, char *argv[]) {
    SSL_library_init();
    OpenSSL_add_all_algorithms();

    SSL_CTX *ctx = create_server_context();
    if (!ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        return 1;
    }

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        SSL_CTX_free(ctx);
        return 1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8443);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) != 0) {
        close(server_fd);
        SSL_CTX_free(ctx);
        return 1;
    }
    if (listen(server_fd, 128) != 0) {
        close(server_fd);
        SSL_CTX_free(ctx);
        return 1;
    }

    printf("Chat server listening on port 8443\n");

    /* Main accept loop would go here */
    close(server_fd);
    SSL_CTX_free(ctx);
    return 0;
}
